package com.game_manager.gm.workflow;
import static org.assertj.core.api.Assertions.assertThat; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.sql.Timestamp; import java.time.Instant; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc; import org.springframework.http.MediaType; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.test.context.ActiveProfiles; import org.springframework.test.web.servlet.*; import tools.jackson.databind.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class WorkflowIntegrationTest {@Autowired MockMvc mvc;@Autowired JdbcTemplate db;@Autowired PasswordEncoder encoder;ObjectMapper json=new ObjectMapper();
 @Test void pilotFlowEnforcesAssignmentReasonHistoryAndOwnerVisibility()throws Exception{UUID owner=user("OWNER"),admin=user("ADMIN"),employee=user("EMPLOYEE"),foreign=user("EMPLOYEE");String ownerToken=login(owner),adminToken=login(admin),employeeToken=login(employee),foreignToken=login(foreign);publish(ownerToken);MvcResult created=create(employeeToken,"Laptop");String id=node(created,"id");long version=Long.parseLong(node(created,"version"));mvc.perform(get("/api/v1/workflows/{id}",id).header("Authorization",bearer(foreignToken))).andExpect(status().isNotFound());mvc.perform(post("/api/v1/workflows/{id}/actions",id).header("Authorization",bearer(adminToken)).contentType(MediaType.APPLICATION_JSON).content("{\"action\":\"REJECT\",\"reason\":\"\",\"version\":"+version+"}")).andExpect(status().isBadRequest());MvcResult approved=mvc.perform(post("/api/v1/workflows/{id}/actions",id).header("Authorization",bearer(adminToken)).contentType(MediaType.APPLICATION_JSON).content("{\"action\":\"APPROVE\",\"version\":"+version+"}")).andExpect(status().isOk()).andExpect(jsonPath("$.workflow.currentStep").value("OWNER_REVIEW")).andReturn();long ownerVersion=json.readTree(approved.getResponse().getContentAsByteArray()).at("/workflow/version").asLong();mvc.perform(post("/api/v1/workflows/{id}/actions",id).header("Authorization",bearer(ownerToken)).contentType(MediaType.APPLICATION_JSON).content("{\"action\":\"APPROVE\",\"version\":"+ownerVersion+"}")).andExpect(status().isOk()).andExpect(jsonPath("$.workflow.status").value("APPROVED")).andExpect(jsonPath("$.decisions.length()").value(2));assertThat(db.queryForObject("SELECT COUNT(*) FROM workflow_decisions WHERE instance_id=?",Long.class,id)).isEqualTo(2);assertThat(db.queryForObject("SELECT COUNT(*) FROM audit_events WHERE resource_id=? AND action='WORKFLOW_DECISION'",Long.class,id)).isEqualTo(2);}
 @Test void concurrentDecisionHasOneWinnerAndOneConflict()throws Exception{UUID owner=user("OWNER"),first=user("ADMIN"),second=user("ADMIN"),employee=user("EMPLOYEE");publish(login(owner));MvcResult created=create(login(employee),"Concurrent");String id=node(created,"id"),payload="{\"action\":\"APPROVE\",\"version\":"+node(created,"version")+"}";String one=login(first),two=login(second);ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);Callable<Integer> call1=()->{start.await();return actStatus(id,one,payload);};Callable<Integer> call2=()->{start.await();return actStatus(id,two,payload);};Future<Integer>a=pool.submit(call1),b=pool.submit(call2);start.countDown();Set<Integer> statuses=Set.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS));pool.shutdownNow();assertThat(statuses).containsExactlyInAnyOrder(200,409);assertThat(db.queryForObject("SELECT COUNT(*) FROM workflow_decisions WHERE instance_id=?",Long.class,id)).isEqualTo(1);}
 private int actStatus(String id,String token,String payload)throws Exception{return mvc.perform(post("/api/v1/workflows/{id}/actions",id).header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content(payload)).andReturn().getResponse().getStatus();}private void publish(String token)throws Exception{mvc.perform(post("/api/v1/workflows/definitions").header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content(definition())).andExpect(status().isCreated());}private MvcResult create(String token,String title)throws Exception{return mvc.perform(post("/api/v1/workflows").header("Authorization",bearer(token)).contentType(MediaType.APPLICATION_JSON).content("{\"definitionKey\":\"EXPENSE_APPROVAL\",\"title\":\""+title+"\",\"amount\":100,\"description\":\"Business equipment\"}")).andExpect(status().isCreated()).andReturn();}private String node(MvcResult r,String key)throws Exception{return json.readTree(r.getResponse().getContentAsByteArray()).get(key).asText();}
 private String definition(){return "{\"key\":\"EXPENSE_APPROVAL\",\"name\":\"Expense approval\",\"initialStep\":\"MANAGER_REVIEW\",\"enabled\":true,\"steps\":[{\"key\":\"MANAGER_REVIEW\",\"label\":\"Manager\",\"role\":\"ADMIN\",\"dueHours\":24,\"reminderHours\":12,\"escalationRole\":\"OWNER\"},{\"key\":\"OWNER_REVIEW\",\"label\":\"Owner\",\"role\":\"OWNER\",\"dueHours\":24,\"reminderHours\":12},{\"key\":\"REQUESTER_REVISION\",\"label\":\"Revision\",\"role\":\"SUBMITTER\",\"dueHours\":48,\"reminderHours\":24}],\"transitions\":[{\"from\":\"MANAGER_REVIEW\",\"action\":\"APPROVE\",\"target\":\"OWNER_REVIEW\",\"reasonRequired\":false},{\"from\":\"MANAGER_REVIEW\",\"action\":\"REJECT\",\"target\":\"REJECTED\",\"reasonRequired\":true},{\"from\":\"MANAGER_REVIEW\",\"action\":\"RETURN\",\"target\":\"REQUESTER_REVISION\",\"reasonRequired\":true},{\"from\":\"OWNER_REVIEW\",\"action\":\"APPROVE\",\"target\":\"APPROVED\",\"reasonRequired\":false},{\"from\":\"OWNER_REVIEW\",\"action\":\"REJECT\",\"target\":\"REJECTED\",\"reasonRequired\":true},{\"from\":\"OWNER_REVIEW\",\"action\":\"RETURN\",\"target\":\"REQUESTER_REVISION\",\"reasonRequired\":true},{\"from\":\"REQUESTER_REVISION\",\"action\":\"SUBMIT\",\"target\":\"MANAGER_REVIEW\",\"reasonRequired\":false},{\"from\":\"REQUESTER_REVISION\",\"action\":\"CANCEL\",\"target\":\"CANCELLED\",\"reasonRequired\":true}]}";}private UUID user(String role){UUID id=UUID.randomUUID();Instant now=Instant.now();db.update("INSERT INTO users(id,name,email,password_hash,role,active,created_at,updated_at,version) VALUES(?,?,?,?,?,?,?,?,0)",id.toString(),role+" User",id+"@example.com",encoder.encode("StrongPass1!"),role,true,Timestamp.from(now),Timestamp.from(now));return id;}private String login(UUID id)throws Exception{String email=db.queryForObject("SELECT email FROM users WHERE id=?",String.class,id.toString());MvcResult result=mvc.perform(post("/api/v1/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"StrongPass1!\"}")).andExpect(status().isOk()).andReturn();return json.readTree(result.getResponse().getContentAsByteArray()).get("token").asText();}private static String bearer(String token){return "Bearer "+token;}}
